import{_ as i,a0 as t,w as o,s as d,I as n,x as a,a1 as l,A as p,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"Docker：使用多阶段构建镜像 | LCTT x X-CMD","titleTemplate":false,"description":"Docker：使用多阶段构建镜像 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Docker：使用多阶段构建镜像 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Docker：使用多阶段构建镜像 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171202 docker - Use multi-stage builds","title":"Docker：使用多阶段构建镜像","tag":"201712","desc":""},"relativePath":"201712/20171202 docker - Use multi-stage builds.md","filePath":"[post].md"}'),c={name:"201712/20171202 docker - Use multi-stage builds.md"};function g(u,s,h,k,b,f){const e=t("Link");return o(),d("div",null,[s[18]||(s[18]=n("h1",{id:"docker-使用多阶段构建镜像",tabindex:"-1"},[a("Docker：使用多阶段构建镜像 "),n("a",{class:"header-anchor",href:"#docker-使用多阶段构建镜像","aria-label":"Permalink to “Docker：使用多阶段构建镜像”"},"​")],-1)),s[19]||(s[19]=n("p",null,"多阶段构建是 Docker 17.05 及更高版本提供的新功能。这对致力于优化 Dockerfile 的人来说，使得 Dockerfile 易于阅读和维护。",-1)),n("blockquote",null,[n("p",null,[s[2]||(s[2]=a("致谢: 特别感谢 ",-1)),l(e,{href:"https://twitter.com/alexellisuk"},{default:p(()=>[...s[0]||(s[0]=[a("Alex Ellis",-1)])]),_:1}),s[3]||(s[3]=a(" 授权使用他的关于 Docker 多阶段构建的博客文章 ",-1)),l(e,{href:"http://blog.alexellis.io/mutli-stage-docker-builds/"},{default:p(()=>[...s[1]||(s[1]=[a("Builder pattern vs. Multi-stage builds in Docker",-1)])]),_:1}),s[4]||(s[4]=a(" 作为以下示例的基础。",-1))])]),s[20]||(s[20]=r(`<h3 id="在多阶段构建之前" tabindex="-1">在多阶段构建之前 <a class="header-anchor" href="#在多阶段构建之前" aria-label="Permalink to “在多阶段构建之前”">​</a></h3><p>关于构建镜像最具挑战性的事情之一是保持镜像体积小巧。 Dockerfile 中的每条指令都会在镜像中增加一层，并且在移动到下一层之前，需要记住清除不需要的构件。要编写一个非常高效的 Dockerfile，你通常需要使用 shell 技巧和其它方式来尽可能地减少层数，并确保每一层都具有上一层所需的构件，而其它任何东西都不需要。</p><p>实际上最常见的是，有一个 Dockerfile 用于开发（其中包含构建应用程序所需的所有内容），而另一个裁剪过的用于生产环境，它只包含您的应用程序以及运行它所需的内容。这被称为“构建器模式”。但是维护两个 Dockerfile 并不理想。</p><p>下面分别是一个 <code>Dockerfile.build</code> 和遵循上面的构建器模式的 <code>Dockerfile</code> 的例子：</p><p><code>Dockerfile.build</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FROM golang:1.7.3</span></span>
<span class="line"><span>WORKDIR /go/src/github.com/alexellis/href-counter/</span></span>
<span class="line"><span>RUN go get -d -v golang.org/x/net/html</span></span>
<span class="line"><span>COPY app.go .</span></span>
<span class="line"><span>RUN go get -d -v golang.org/x/net/html \\</span></span>
<span class="line"><span>  &amp;&amp; CGO_ENABLED=0 GOOS=linux go build -a -installsuffix cgo -o app .</span></span></code></pre></div><p>注意这个例子还使用 Bash 的 <code>&amp;&amp;</code> 运算符人为地将两个 <code>RUN</code> 命令压缩在一起，以避免在镜像中创建额外的层。这很容易失败，难以维护。例如，插入另一个命令时，很容易忘记继续使用 <code>\\</code> 字符。</p><p><code>Dockerfile</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FROM alpine:latest</span></span>
<span class="line"><span>RUN apk --no-cache add ca-certificates</span></span>
<span class="line"><span>WORKDIR /root/</span></span>
<span class="line"><span>COPY app .</span></span>
<span class="line"><span>CMD [&quot;./app&quot;]</span></span></code></pre></div><p><code>build.sh</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span>echo Building alexellis2/href-counter:build</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docker build --build-arg https_proxy=$https_proxy --build-arg http_proxy=$http_proxy \\</span></span>
<span class="line"><span>    -t alexellis2/href-counter:build . -f Dockerfile.build</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docker create --name extract alexellis2/href-counter:build</span></span>
<span class="line"><span>docker cp extract:/go/src/github.com/alexellis/href-counter/app ./app</span></span>
<span class="line"><span>docker rm -f extract</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo Building alexellis2/href-counter:latest</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docker build --no-cache -t alexellis2/href-counter:latest .</span></span>
<span class="line"><span>rm ./app</span></span></code></pre></div><p>当您运行 <code>build.sh</code> 脚本时，它会构建第一个镜像，从中创建一个容器，以便将该构件复制出来，然后构建第二个镜像。 这两个镜像会占用您的系统的空间，而你仍然会一个 <code>app</code> 构件存放在你的本地磁盘上。</p><p>多阶段构建大大简化了这种情况！</p><h3 id="使用多阶段构建" tabindex="-1">使用多阶段构建 <a class="header-anchor" href="#使用多阶段构建" aria-label="Permalink to “使用多阶段构建”">​</a></h3><p>在多阶段构建中，您需要在 Dockerfile 中多次使用 <code>FROM</code> 声明。每次 <code>FROM</code> 指令可以使用不同的基础镜像，并且每次 <code>FROM</code> 指令都会开始新阶段的构建。您可以选择将构件从一个阶段复制到另一个阶段，在最终镜像中，不会留下您不需要的所有内容。为了演示这是如何工作的，让我们调整前一节中的 Dockerfile 以使用多阶段构建。</p><p><code>Dockerfile</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FROM golang:1.7.3</span></span>
<span class="line"><span>WORKDIR /go/src/github.com/alexellis/href-counter/</span></span>
<span class="line"><span>RUN go get -d -v golang.org/x/net/html</span></span>
<span class="line"><span>COPY app.go .</span></span>
<span class="line"><span>RUN CGO_ENABLED=0 GOOS=linux go build -a -installsuffix cgo -o app .</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FROM alpine:latest</span></span>
<span class="line"><span>RUN apk --no-cache add ca-certificates</span></span>
<span class="line"><span>WORKDIR /root/</span></span>
<span class="line"><span>COPY --from=0 /go/src/github.com/alexellis/href-counter/app .</span></span>
<span class="line"><span>CMD [&quot;./app&quot;]</span></span></code></pre></div><p>您只需要单一个 Dockerfile。 不需要另外的构建脚本。只需运行 <code>docker build</code> 即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker build -t alexellis2/href-counter:latest .</span></span></code></pre></div><p>最终的结果是和以前体积一样小的生产镜像，复杂性显著降低。您不需要创建任何中间镜像，也不需要将任何构件提取到本地系统。</p><p>它是如何工作的呢？第二条 <code>FROM</code> 指令以 <code>alpine:latest</code> 镜像作为基础开始新的建造阶段。<code>COPY --from=0</code> 这一行将刚才前一个阶段产生的构件复制到这个新阶段。Go SDK 和任何中间构件都被留在那里，而不会保存到最终的镜像中。</p><h3 id="命名您的构建阶段" tabindex="-1">命名您的构建阶段 <a class="header-anchor" href="#命名您的构建阶段" aria-label="Permalink to “命名您的构建阶段”">​</a></h3><p>默认情况下，这些阶段没有命名，您可以通过它们的整数来引用它们，从第一个 <code>FROM</code> 指令的 0 开始。但是，你可以通过在 <code>FROM</code> 指令中使用 <code>as &lt;NAME&gt;</code> 来为阶段命名。以下示例通过命名阶段并在 <code>COPY</code> 指令中使用名称来改进前一个示例。这意味着，即使您的 <code>Dockerfile</code> 中的指令稍后重新排序，<code>COPY</code> 也不会出问题。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FROM golang:1.7.3 as builder</span></span>
<span class="line"><span>WORKDIR /go/src/github.com/alexellis/href-counter/</span></span>
<span class="line"><span>RUN go get -d -v golang.org/x/net/html</span></span>
<span class="line"><span>COPY app.go    .</span></span>
<span class="line"><span>RUN CGO_ENABLED=0 GOOS=linux go build -a -installsuffix cgo -o app .</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FROM alpine:latest</span></span>
<span class="line"><span>RUN apk --no-cache add ca-certificates</span></span>
<span class="line"><span>WORKDIR /root/</span></span>
<span class="line"><span>COPY --from=builder /go/src/github.com/alexellis/href-counter/app .</span></span>
<span class="line"><span>CMD [&quot;./app&quot;]</span></span></code></pre></div><hr>`,25)),n("p",null,[s[6]||(s[6]=a("via: ",-1)),l(e,{href:"https://docs.docker.com/engine/userguide/eng-image/multistage-build/"},{default:p(()=>[...s[5]||(s[5]=[a("https://docs.docker.com/engine/userguide/eng-image/multistage-build/",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=a("作者：",-1)),l(e,{href:"https://docs.docker.com/engine/userguide/eng-image/multistage-build/"},{default:p(()=>[...s[7]||(s[7]=[a("docker",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),l(e,{href:"https://github.com/iron0x"},{default:p(()=>[...s[8]||(s[8]=[a("iron0x",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const C=i(c,[["render",g]]);export{D as __pageData,C as default};
